N_KNOTS<-6;N_GRID<-160
suppressPackageStartupMessages({library(data.table);library(mgcv)})
a<-grep('^--file=',commandArgs(),value=T);base<-dirname(dirname(normalizePath(sub('^--file=','',a[1]))));setwd(base)
m<-fread('inputs/cells.csv');xx<-fread('inputs/corrected_intensity.csv');X<-as.matrix(xx[,-1]);stopifnot(identical(xx$cell_id,m$cell_id),all(m$day!='D0'),length(unique(m$pseudotime))>=N_KNOTS)
grid<-seq(quantile(m$pseudotime,.05),quantile(m$pseudotime,.95),length.out=N_GRID);nd<-data.frame(pseudotime=grid)
one<-function(i){dd<-data.frame(pseudotime=m$pseudotime,y=X[,i]);fit<-gam(y~s(pseudotime,k=N_KNOTS,bs='cr'),data=dd,family=gaussian(),method='REML');pr<-predict(fit,nd,se.fit=T,unconditional=T);L<-predict(fit,nd[c(1,N_GRID),,drop=F],type='lpmatrix');C<-L[2,]-L[1,];delta<-sum(C*coef(fit));se<-sqrt(drop(C%*%vcov(fit,unconditional=T)%*%C));st<-summary(fit)$s.table;list(stats=data.table(feature_id=colnames(X)[i],association_p_Osi=st[1,'p-value'],edf=st[1,'edf'],startEnd_delta_Osi=delta,startEnd_se=se,startEnd_p_Osi=2*pnorm(-abs(delta/se)),n_cells=nrow(dd),fit_ok=TRUE),pred=as.numeric(pr$fit),se=as.numeric(pr$se.fit))}
res<-parallel::mclapply(seq_len(ncol(X)),one,mc.cores=2);stopifnot(!any(vapply(res,inherits,logical(1),'try-error')));s<-rbindlist(lapply(res,`[[`,'stats'));s[,`:=`(association_BH_FDR_Osi=p.adjust(association_p_Osi,'BH'),startEnd_BH_FDR_Osi=p.adjust(startEnd_p_Osi,'BH'),BH_family_size=.N)];fwrite(s,'tables/all_features_GAM_significance.csv');for(n in c('pred','se')){v<-do.call(rbind,lapply(res,`[[`,n));colnames(v)<-sprintf('T%03d',1:N_GRID);fwrite(data.table(feature_id=colnames(X),as.data.table(v)),paste0('tables/GAM_',n,'.csv'))};fwrite(data.table(column=sprintf('T%03d',1:N_GRID),pseudotime=grid),'tables/GAM_pseudotime_grid.csv');cat('GAM',nrow(s),'features;',sum(s$association_BH_FDR_Osi<.05),'significant\n')
